"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2798],{32798:e=>{e.exports=JSON.parse('{"callId":"call_linda_ac","audioUrl":null,"duration":247,"segments":[{"startMs":0,"endMs":3800,"speaker":"ava","text":"Thank you for calling Northwind Heating and Air. I\'m Northwind\'s AI assistant. How can I help you today?"},{"startMs":4200,"endMs":9500,"speaker":"customer","text":"Hi, my AC completely stopped working. It\'s 102 degrees outside and I have my kids home. This is an emergency for us."},{"startMs":9900,"endMs":16000,"speaker":"ava","text":"I completely understand — that sounds really uncomfortable, especially with kids at home. Let me pull up your account right now so I can help you as fast as possible."},{"startMs":16400,"endMs":20000,"speaker":"customer","text":"My name is Linda Harris, I\'m at 2672 Barton Hills Drive."},{"startMs":20400,"endMs":28000,"speaker":"ava","text":"Got it, Linda. I found your account. I can see you have a Carrier AC unit installed back in 2014 — so it\'s about 12 years old. I\'m checking your warranty now... I do see that the manufacturer warranty expired in May 2024, but let me check if there\'s anything else we can do. I also see you\'re a Comfort Club member — that gives you priority scheduling."},{"startMs":28400,"endMs":32000,"speaker":"customer","text":"Okay, yes. When can someone come out? Today if possible?"},{"startMs":32400,"endMs":42000,"speaker":"ava","text":"Absolutely. Looking at today\'s schedule, I have a slot available from 2pm to 4pm this afternoon. We\'d send Dev Patel — he\'s one of our senior technicians, R-410A certified, and he has a 98% first-time fix rate. Given it\'s a Carrier unit and July heat, he\'d be my top recommendation. Does the 2 to 4pm window work for you?"},{"startMs":42400,"endMs":45000,"speaker":"customer","text":"Yes, that\'s perfect. 2 to 4pm works."},{"startMs":45400,"endMs":56000,"speaker":"ava","text":"Great, Linda. I\'ve booked Dev Patel for today, 2pm to 4pm, at 2672 Barton Hills Drive for an AC repair. You\'ll get a text confirmation shortly, and you can track Dev\'s arrival on a live map once he\'s on his way. Is there anything else I can help you with?"},{"startMs":56400,"endMs":59000,"speaker":"customer","text":"No, that\'s great. Thank you so much."},{"startMs":59400,"endMs":63000,"speaker":"ava","text":"You\'re welcome, Linda. Stay cool as best you can, and Dev will be there this afternoon. Have a great day!"}],"extractedFields":{"name":"Linda Harris","address":"2672 Barton Hills Drive","issue":"AC not cooling","urgency":"high","equipment":"Carrier AC 2014","preferredWindow":"2pm–4pm"},"sentimentBySegment":[0,-0.6,0.2,0.1,0.3,-0.2,0.5,0.7,0.8,0.9,0.9],"bookingCard":{"jobId":"job_linda_ac_today","window":{"start":"14:00","end":"16:00","date":"2026-07-15"},"techName":"Dev Patel","confirmationNumber":"NW-20260715-001"},"reasoning":"Customer identified as existing member (Comfort Club). Equipment age flagged as 12 years — warranty expired. Priority slot offered given membership tier. Dev Patel selected based on R-410A certification, proximity (4.2 mi), and 98% first-time fix rate. No emergency keywords detected; standard booking flow completed."}')}}]);